        $x = number_format($user->seti_total_cpu/3600)." hours";
        row2("SETI@home classic CPU time", $x);
    }
    */
    return $retstr;
}

function show_user_wap($user)
{

//   wap_begin();

   if (!$user) {
      echo "<br/>User not found!<br/>";
  //    wap_end();
      return;
   }

    // keep a 'running tab' in wapstr in case exceeds 1K WAP limit

